def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    if n == 1:
        return 'D' if op[0] == 'D' else 'C'

    last_opp = op[-1]
    last_me = me[-1]
    prev_me = me[-2]

    opp_d = sum(1 for x in op if x == 'D')
    recent_d = sum(1 for x in op[-5:] if x == 'D')

    punish = 0
    forgive = 0
    dc = 0
    cd = 0

    for i in range(1, n):
        if me[i - 1] == 'D':
            if op[i] == 'D':
                punish += 1
            else:
                forgive += 1

        if op[i] == 'D':
            if op[i - 1] == 'C':
                dc += 1
        else:
            if op[i - 1] == 'D':
                cd += 1

    if last_opp == 'D':
        if opp_d * 2 >= n or recent_d >= 4:
            return 'D'

        if prev_me == 'D' and opp_d <= max(2, (n * 3) // 10) and recent_d <= 2:
            return 'C'

        if prev_me == 'D' and forgive > punish and rng.random() < 0.35:
            return 'C'

        return 'D'

    if last_me == 'D':
        if punish == 0 and forgive > 0 and opp_d <= max(3, n // 3) and recent_d == 0:
            if n >= 90 and rng.random() < 0.65:
                return 'D'
            if rng.random() < 0.25:
                return 'D'
        return 'C'

    if n >= 5 and recent_d >= 3:
        return 'D'

    if n >= 10 and opp_d <= max(4, (n * 2) // 5):
        if cd > dc + 2:
            if rng.random() < 0.3:
                return 'D'

    if punish == 0 and forgive >= 1 and opp_d == 0 and recent_d == 0:
        if n >= 70 and rng.random() < 0.25:
            return 'D'

    if punish == 0 and forgive >= 2 and opp_d <= max(3, n // 4):
        if n >= 80 and rng.random() < 0.5:
            return 'D'
        if rng.random() < 0.04:
            return 'D'

    if n >= 96 and punish == 0 and forgive >= 1 and recent_d == 0:
        return 'D' if rng.random() < 0.7 else 'C'

    return 'C'
